mapper.update:
UPDATE member_reminder
SET status = #{status}
WHERE id = #{id}

mapper.select:
SELECT id, user_id, remind_time, channel, status, created_at
FROM member_reminder
WHERE id = #{id}

SELECT id, user_id, remind_time, channel, status, created_at
FROM member_reminder
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM member_reminder
WHERE user_id = #{userId}

SELECT id, user_id, remind_time, channel, status, created_at
FROM member_reminder
WHERE channel = #{channel}
  AND status = 'PENDING'
ORDER BY created_at ASC
LIMIT #{limit} OFFSET #{offset}

SELECT EXISTS(
    SELECT 1 FROM member_reminder
    WHERE user_id = #{userId}
      AND remind_time = #{remindTime}
      AND channel = #{channel}
)
